SELECT category, period, SUM(net_cents)/100.0 AS net_sales, SUM(pre_refund_cents)/100.0 AS pre_refund_sales, SUM(refund_amount_cents)/100.0 AS refund_amount, SUM(refund_amount_cents)*1.0/NULLIF(SUM(pre_refund_cents),0) AS refund_rate, COUNT(DISTINCT order_id) AS order_count, SUM(net_cents)/100.0/COUNT(DISTINCT order_id) AS net_aov FROM items WHERE period IN ('control','analysis') AND category='家居' GROUP BY category, period ORDER BY period;